/* Page Scan. All image processing and exports are local to the browser. */
'use strict';
const $=id=>document.getElementById(id),Core=ScannerCore;
const source=document.createElement('canvas'),ctx=source.getContext('2d',{willReadFrequently:true});
const editor=$('editorCanvas'),ec=editor.getContext('2d'),result=$('resultCanvas');
let points=[],mode='color',landscape=false,view='original',stream=null,busy=false,revision=0,lastScan=-1,saved=[],physical=null,demo=true,loadToken=0,feedbackTimer;
function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error);}
function markDirty(){revision++;if(view==='result')showView('original');$('exportActions').hidden=true;}
function showView(which){view=which;const original=which==='original';$('canvasWrap').hidden=!original;result.hidden=original;$('originalTab').classList.toggle('active',original);$('resultTab').classList.toggle('active',!original);$('originalTab').setAttribute('aria-selected',original);$('resultTab').setAttribute('aria-selected',!original);$('stageTip').textContent=original?'Drag the corners to the page edges.':'Check the result, then download or add to scans.';}
function render(){
 editor.width=source.width;editor.height=source.height;ec.drawImage(source,0,0);if(points.length!==4)return;
 ec.save();ec.fillStyle='rgba(27,39,27,.36)';ec.beginPath();ec.rect(0,0,source.width,source.height);ec.moveTo(points[0].x,points[0].y);for(let i=3;i>=0;i--)ec.lineTo(points[i].x,points[i].y);ec.closePath();ec.fill('evenodd');ec.strokeStyle='#b79add';ec.lineWidth=Math.max(2,source.width/550);ec.beginPath();points.forEach((p,i)=>i?ec.lineTo(p.x,p.y):ec.moveTo(p.x,p.y));ec.closePath();ec.stroke();ec.restore();
 [...$('handles').children].forEach((h,i)=>{h.style.left=points[i].x/source.width*100+'%';h.style.top=points[i].y/source.height*100+'%';});
}
function makeHandles(){
 $('handles').replaceChildren();const names=['Top left','Top right','Bottom right','Bottom left'];
 names.forEach((name,i)=>{const h=document.createElement('button');h.className='corner';h.setAttribute('aria-label',name+' corner. Use arrow keys to move.');h.title=name;h.addEventListener('pointerdown',e=>{if(busy)return;e.preventDefault();h.setPointerCapture(e.pointerId);});h.addEventListener('pointermove',e=>{if(!h.hasPointerCapture(e.pointerId)||busy)return;const r=editor.getBoundingClientRect();points[i]={x:Math.max(0,Math.min(source.width-1,(e.clientX-r.left)/r.width*source.width)),y:Math.max(0,Math.min(source.height-1,(e.clientY-r.top)/r.height*source.height))};markDirty();render();});h.addEventListener('pointerup',e=>{if(h.hasPointerCapture(e.pointerId))h.releasePointerCapture(e.pointerId);});h.addEventListener('keydown',e=>{const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!d||busy)return;e.preventDefault();const step=e.shiftKey?10:1;points[i].x=Math.max(0,Math.min(source.width-1,points[i].x+d[0]*step));points[i].y=Math.max(0,Math.min(source.height-1,points[i].y+d[1]*step));markDirty();render();});$('handles').append(h);});
}
function defaultCorners(){const w=source.width-1,h=source.height-1;points=[{x:w*.06,y:h*.06},{x:w*.94,y:h*.06},{x:w*.94,y:h*.94},{x:w*.06,y:h*.94}];}
function detectPage(announce=true){
 const c=document.createElement('canvas'),scale=Math.min(1,600/Math.max(source.width,source.height));c.width=Math.max(1,Math.round(source.width*scale));c.height=Math.max(1,Math.round(source.height*scale));const cc=c.getContext('2d',{willReadFrequently:true});cc.drawImage(source,0,0,c.width,c.height);const q=Core.detect(cc.getImageData(0,0,c.width,c.height).data,c.width,c.height);
 if(q){points=q.map(p=>({x:p.x/scale,y:p.y/scale}));if(announce)notice('Page suggested. Check all four corners before straightening.');}else{if(announce)notice('No clear page boundary found. Place the four corners yourself.');}markDirty();render();return !!q;
}
function loadCanvas(c,isDemo=false){source.width=c.width;source.height=c.height;ctx.drawImage(c,0,0);demo=isDemo;$('sampleLabel').textContent=isDemo?'SAMPLE PAGE':'YOUR PHOTO';defaultCorners();makeHandles();markDirty();detectPage(false);showView('original');notice(isDemo?'Try the sample, or import your own page to begin.':'Photo ready. Check the corner positions and choose a page size.');}
async function importFile(file){
 if(!file)return;if(!file.type.startsWith('image/')){notice('Choose a photograph, such as JPEG, PNG or WebP. PDF import is not included.',true);return;}
 if(file.size>60*1024*1024){notice('This image exceeds the 60 MB import limit. Please choose a smaller image.',true);return;}
 const token=++loadToken;try{const url=URL.createObjectURL(file),im=new Image();try{im.src=url;await im.decode();if(token!==loadToken)return;const scale=Math.min(1,2800/Math.max(im.naturalWidth,im.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(im.naturalWidth*scale);c.height=Math.round(im.naturalHeight*scale);if(!c.width||!c.height)throw Error('Empty image');c.getContext('2d').drawImage(im,0,0,c.width,c.height);loadCanvas(c);if(scale<1)notice('Photo loaded at a reduced size for mobile processing. Check the four corners.');}finally{URL.revokeObjectURL(url);}}catch(e){notice('This browser could not decode the image. Try JPEG or PNG instead.',true);}
}
function getPhysical(){let p=$('paperSize').value;if(p==='auto')return null;let w,h;if(p==='custom'){w=Number($('customWidth').value);h=Number($('customHeight').value);if(!Number.isFinite(w)||!Number.isFinite(h)||w<10||h<10||w>5000||h>5000)throw Error('Enter a width and height between 10 and 5,000 mm.');}else{[w,h]=p.split(',').map(Number);if(landscape)[w,h]=[h,w];}return {w,h};}
async function straighten(){
 if(busy)return false;try{physical=getPhysical();if(!Core.validQuad(points))throw Error('The page edges cross. Put the corners in top-left, top-right, bottom-right, bottom-left order.');busy=true;$('working').hidden=false;$('scanBtn').disabled=true;await new Promise(r=>setTimeout(r,30));const target=Core.outputSize(points,physical),pixels=ctx.getImageData(0,0,source.width,source.height),out=Core.warp(pixels.data,source.width,source.height,points,target.w,target.h,mode,Number($('exposure').value));result.width=target.w;result.height=target.h;result.getContext('2d').putImageData(new ImageData(out,target.w,target.h),0,0);lastScan=revision;showView('result');$('exportActions').hidden=false;$('resolutionInfo').textContent=`${target.w} × ${target.h} px · ${physical?physical.w+' × '+physical.h+' mm':'estimated proportions'}${target.limited?' · resolution capped':''}`;notice(demo?'Sample straightened. Import your own page whenever you are ready.':'Scan ready. Download it now, or add it to a multi-page PDF.');return true;}catch(e){notice(e.message,true);return false;}finally{busy=false;$('working').hidden=true;$('scanBtn').disabled=false;}}
async function ensureResult(){return lastScan===revision||await straighten();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function filename(ext){return 'page-scan-'+new Date().toISOString().slice(0,10)+'.'+ext;}
async function downloadImage(type){if(!await ensureResult())return;result.toBlob(b=>{if(b)download(b,filename(type==='image/png'?'png':'jpg'));else notice('Image export failed. Please try again.',true);},type,.94);}
async function addPage(){if(!await ensureResult())return;if(saved.length>=20){notice('This session holds up to 20 pages. Download the PDF, then clear scans to continue.',true);return;}const data=result.toDataURL('image/jpeg',.92);saved.push({data,w:result.width,h:result.height,physical:physical?{...physical}:null,sample:demo});renderSaved();notice('Page added to this session. Download your PDF before leaving.');}
function renderSaved(){
 $('pageCount').textContent=String(saved.length).padStart(2,'0');$('pdfBtn').disabled=!saved.length;$('clearBtn').disabled=!saved.length;const grid=$('savedGrid');grid.replaceChildren();if(!saved.length){const el=document.createElement('div');el.className='empty-state';el.innerHTML='<span class="empty-icon">▱</span><p>Your next chapter starts here.</p><span>Straighten a page, then add it to your scans.</span>';grid.append(el);return;}
 saved.forEach((p,i)=>{const card=document.createElement('article');card.className='saved-card';const img=new Image();img.src=p.data;img.alt=`Scanned page ${i+1}${p.sample?' (sample)':''}`;card.append(img);const row=document.createElement('div');row.className='saved-card-bottom';const label=document.createElement('span');label.textContent=`${String(i+1).padStart(2,'0')}${p.sample?' · sample':''}`;const actions=document.createElement('div');actions.className='card-actions';for(const [symbol,title,fn,disabled] of [['←','Move page earlier',()=>{[saved[i-1],saved[i]]=[saved[i],saved[i-1]];renderSaved();},i===0],['→','Move page later',()=>{[saved[i+1],saved[i]]=[saved[i],saved[i+1]];renderSaved();},i===saved.length-1],['×','Remove page',()=>{saved.splice(i,1);renderSaved();},false]]){const b=document.createElement('button');b.textContent=symbol;b.title=title;b.setAttribute('aria-label',title);b.disabled=disabled;b.onclick=fn;actions.append(b);}row.append(label,actions);card.append(row);grid.append(card);});
}
function makePDF(pages){
 // Minimal PDF 1.4 writer: JPEG images on individual pages, with explicit MediaBox.
 const enc=new TextEncoder(),chunks=[],offsets=[0];let length=0;const push=b=>{const bytes=typeof b==='string'?enc.encode(b):b;chunks.push(bytes);length+=bytes.length;},obj=(n,body)=>{offsets[n]=length;push(`${n} 0 obj\n`);push(body);push('\nendobj\n');};
 push('%PDF-1.4\n% Page Scan\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);
 pages.forEach((p,i)=>{const n=3+i*3,ratio=p.w/p.h;let pw,ph;if(p.physical){pw=p.physical.w/25.4*72;ph=p.physical.h/25.4*72;}else{ph=792;pw=ph*ratio;}const bin=atob(p.data.split(',')[1]),jpeg=Uint8Array.from(bin,c=>c.charCodeAt(0));const content=`q\n${pw.toFixed(4)} 0 0 ${ph.toFixed(4)} 0 0 cm\n/Im0 Do\nQ\n`;obj(n,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw.toFixed(4)} ${ph.toFixed(4)}] /Resources << /XObject << /Im0 ${n+1} 0 R >> >> /Contents ${n+2} 0 R >>`);offsets[n+1]=length;push(`${n+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${p.w} /Height ${p.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);push(jpeg);push('\nendstream\nendobj\n');obj(n+2,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}endstream`);});
 const xref=length,count=3+pages.length*3;push(`xref\n0 ${count}\n0000000000 65535 f \n`);for(let i=1;i<count;i++)push(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size ${count} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);return new Blob(chunks,{type:'application/pdf'});
}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}$('cameraVideo').srcObject=null;}
async function openCamera(){if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){$('mobileCameraInput').click();return;}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:2400},height:{ideal:3200}},audio:false});$('cameraVideo').srcObject=stream;$('cameraDialog').showModal();}catch(e){stopCamera();notice('Camera access is unavailable or was declined. Use Import photo or your device camera instead.');$('mobileCameraInput').click();}}
function capture(){const v=$('cameraVideo');if(!v.videoWidth){notice('The camera is still starting. Try again in a moment.');return;}const c=document.createElement('canvas'),s=Math.min(1,2800/Math.max(v.videoWidth,v.videoHeight));c.width=Math.round(v.videoWidth*s);c.height=Math.round(v.videoHeight*s);c.getContext('2d').drawImage(v,0,0,c.width,c.height);loadCanvas(c);$('cameraDialog').close();}
function sample(){
 const page=document.createElement('canvas');page.width=650;page.height=900;const p=page.getContext('2d');p.fillStyle='#fffdf5';p.fillRect(0,0,650,900);p.strokeStyle='#33392f';p.lineWidth=7;p.strokeRect(25,25,600,850);p.fillStyle='#c5c8ba';for(let y=58;y<850;y+=21)for(let x=55;x<610;x+=21){p.beginPath();p.arc(x,y,.9,0,Math.PI*2);p.fill();}
 p.fillStyle='#5f6a57';p.font='12px sans-serif';p.fillText('SUNDAY, OCTOBER 25',66,104);p.fillStyle='#35422f';p.font='italic 40px Georgia';p.fillText('Things worth keeping.',64,168);p.font='17px Georgia';const lines=['The first quiet moment of the morning.','A warm mug. A page with room to think.'];lines.forEach((s,i)=>p.fillText(s,66,220+i*29));p.strokeStyle='#b8bfa9';p.lineWidth=1;p.beginPath();p.moveTo(66,295);p.lineTo(576,295);p.stroke();p.font='12px sans-serif';p.fillStyle='#6f7963';p.fillText('A SMALL PLAN',66,342);p.font='19px Georgia';p.fillStyle='#3c4734';['Make something with my hands','Leave a little space between things','Write one thing I want to remember'].forEach((s,i)=>{p.strokeRect(68,375+i*47,13,13);p.fillText(s,95,387+i*47);});p.font='12px sans-serif';p.fillText('A NOTE TO MYSELF',66,575);p.font='italic 24px Georgia';['A small beginning is still','a beginning.'].forEach((s,i)=>p.fillText(s,66,624+i*33));p.font='11px sans-serif';p.fillStyle='#7d886f';p.fillText('A SAMPLE PAGE · YOUR WRITING GOES HERE',66,823);
 const c=document.createElement('canvas');c.width=960;c.height=1080;const cc=c.getContext('2d'),data=cc.createImageData(c.width,c.height);for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++){const i=(y*c.width+x)*4;const noise=Math.sin(x*.04+y*.7)*2;data.data[i]=113+noise;data.data[i+1]=124+noise;data.data[i+2]=101+noise;data.data[i+3]=255;}cc.putImageData(data,0,0);const q=[{x:130,y:70},{x:814,y:125},{x:847,y:1010},{x:77,y:940}],m=Core.homography(q);
 // For the demo, map each scanline by triangulation-free inverse homography.
 const inv=invert3([m[0],m[1],m[2],m[3],m[4],m[5],m[6],m[7],1]),pix=p.getImageData(0,0,650,900).data,out=cc.getImageData(0,0,c.width,c.height);
 for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++){const z=inv[6]*x+inv[7]*y+inv[8],u=(inv[0]*x+inv[1]*y+inv[2])/z,v=(inv[3]*x+inv[4]*y+inv[5])/z;if(u<0||v<0||u>1||v>1)continue;const a=(Math.min(899,Math.floor(v*900))*650+Math.min(649,Math.floor(u*650)))*4,b=(y*c.width+x)*4;out.data[b]=pix[a];out.data[b+1]=pix[a+1];out.data[b+2]=pix[a+2];out.data[b+3]=255;}cc.putImageData(out,0,0);loadCanvas(c,true);
}
function invert3(m){const [a,b,c,d,e,f,g,h,i]=m,A=e*i-f*h,B=c*h-b*i,C=b*f-c*e,D=f*g-d*i,E=a*i-c*g,F=c*d-a*f,G=d*h-e*g,H=b*g-a*h,I=a*e-b*d,det=a*A+b*D+c*G;return [A,B,C,D,E,F,G,H,I].map(x=>x/det);}
$('importBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>{importFile(e.target.files[0]);e.target.value='';};$('mobileCameraInput').onchange=e=>{importFile(e.target.files[0]);e.target.value='';};$('cameraBtn').onclick=openCamera;$('closeCamera').onclick=()=>$('cameraDialog').close();$('cameraDialog').addEventListener('close',stopCamera);$('cameraDialog').addEventListener('cancel',stopCamera);$('captureBtn').onclick=capture;$('nativeCameraBtn').onclick=()=>{$('cameraDialog').close();$('mobileCameraInput').click();};document.addEventListener('visibilitychange',()=>{if(document.hidden&&stream)$('cameraDialog').close();});
$('helpBtn').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('sampleBtn').onclick=()=>{if(!busy){loadToken++;sample();}};$('detectBtn').onclick=()=>{if(!busy)detectPage();};$('resetBtn').onclick=()=>{if(!busy){defaultCorners();markDirty();render();notice('Corners reset. Drag them to the four edges of your page.');}};$('rotateBtn').onclick=()=>{if(busy)return;const c=document.createElement('canvas');c.width=source.height;c.height=source.width;const cc=c.getContext('2d');cc.translate(c.width,0);cc.rotate(Math.PI/2);cc.drawImage(source,0,0);loadCanvas(c,demo);};
$('originalTab').onclick=()=>showView('original');$('resultTab').onclick=async()=>{if(await ensureResult())showView('result');};$('scanBtn').onclick=straighten;$('pngBtn').onclick=()=>downloadImage('image/png');$('jpgBtn').onclick=()=>downloadImage('image/jpeg');$('saveBtn').onclick=addPage;$('pdfBtn').onclick=()=>{try{if(saved.length){download(makePDF(saved),filename('pdf'));notice('PDF downloaded. Your scans are still available in this tab.');}}catch(e){notice('PDF export failed: '+e.message,true);}};$('clearBtn').onclick=()=>{if(confirm('Clear all scans from this tab? Download the PDF first if you want to keep them.')){saved=[];renderSaved();notice('Session scans cleared.');}};
$('paperSize').onchange=()=>{const v=$('paperSize').value;$('customDimensions').hidden=v!=='custom';$('orientation').hidden=v==='auto'||v==='custom';markDirty();};for(const id of ['customWidth','customHeight'])$(id).oninput=markDirty;
function orient(l){landscape=l;$('portraitBtn').classList.toggle('selected',!l);$('landscapeBtn').classList.toggle('selected',l);$('portraitBtn').setAttribute('aria-pressed',!l);$('landscapeBtn').setAttribute('aria-pressed',l);markDirty();}$('portraitBtn').onclick=()=>orient(false);$('landscapeBtn').onclick=()=>orient(true);$('orientation').hidden=true;
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>{const s=x===b;x.classList.toggle('selected',s);x.setAttribute('aria-pressed',s);});markDirty();});$('exposure').oninput=()=>{$('exposureValue').textContent=$('exposure').value;markDirty();};
for(const evt of ['dragenter','dragover'])$('dropZone').addEventListener(evt,e=>{e.preventDefault();$('dropZone').classList.add('dragover');});for(const evt of ['dragleave','drop'])$('dropZone').addEventListener(evt,e=>{e.preventDefault();$('dropZone').classList.remove('dragover');if(evt==='drop')importFile(e.dataTransfer.files[0]);});
window.addEventListener('pagehide',stopCamera);window.addEventListener('beforeunload',e=>{if(saved.length){e.preventDefault();e.returnValue='';}});sample();

const insertScan=document.createElement('button');insertScan.className='button';insertScan.textContent='Insert scan in Jot';$('saveBtn').after(insertScan);
insertScan.onclick=async()=>{if(!await ensureResult())return;insertScan.disabled=true;try{const blob=await new Promise(resolve=>result.toBlob(resolve,'image/png'));if(!blob)throw Error('Image export failed.');const path='assets/scan-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)+'.png';const {queueCapture}=await import('../jot/storage.mjs');await queueCapture({assets:[{path,mediaType:'image/png',data:new Uint8Array(await blob.arrayBuffer())}],text:'![Scanned journal page]('+path+')'});window.location.href='../write/';}catch(e){notice('Could not insert scan: '+e.message,true);}finally{insertScan.disabled=false;}};
